import "container/heap"

func findKthLargest(nums []int, k int) int {
	h := &minHeap{}
	for _, n := range nums {
		heap.Push(h, n)
		if h.Len() > k {
			heap.Pop(h)
		}
	}
	return (*h)[0]
}

