func subsets(nums []int) [][]int {
	var out [][]int
	var cur []int
	var walk func(i int)
	walk = func(i int) {
		if i == len(nums) {
			out = append(out, append([]int(nil), cur...))
			return
		}
		walk(i + 1)
		cur = append(cur, nums[i])
		walk(i + 1)
		cur = cur[:len(cur)-1]
	}
	walk(0)
	return out
}

