func subsetKey(sub []int) string {
	s := append([]int(nil), sub...)
	sort.Ints(s)
	return fmt.Sprint(s)
}

func TestSubsets(t *testing.T) {
	cases := []struct {
		nums []int
		want []string
	}{
		{[]int{1, 2, 3}, []string{"[]", "[1]", "[2]", "[3]", "[1 2]", "[1 3]", "[2 3]", "[1 2 3]"}},
		{[]int{0}, []string{"[]", "[0]"}},
		{nil, []string{"[]"}},
	}
	for _, c := range cases {
		got := subsets(c.nums)
		if len(got) != len(c.want) {
			t.Fatalf("subsets(%v) returned %d subsets, want %d", c.nums, len(got), len(c.want))
		}
		seen := map[string]bool{}
		for _, sub := range got {
			seen[subsetKey(sub)] = true
		}
		for _, w := range c.want {
			if !seen[w] {
				t.Errorf("subsets(%v) is missing %s", c.nums, w)
			}
		}
	}
}

